create table public.communication_preferences(user_id uuid primary key references auth.users(id) on delete cascade,email_enabled boolean not null default true,interview_reminders boolean not null default true,weekly_summary boolean not null default true,whatsapp_enabled boolean not null default false,sms_enabled boolean not null default false,quiet_hours_start time,quiet_hours_end time,timezone text not null default 'Asia/Kolkata',updated_at timestamptz not null default now());
create table public.data_subject_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,request_type text not null check(request_type in ('export','correction','deletion','consent_history')),detail text,status text not null default 'submitted' check(status in ('submitted','identity_check','processing','completed','partially_completed','rejected','cancelled')),due_at timestamptz,completion_note text,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.user_sessions(user_id uuid not null references auth.users(id) on delete cascade,session_id_hash text not null,device_label text,ip_region text,last_seen_at timestamptz not null default now(),revoked_at timestamptz,primary key(user_id,session_id_hash));
alter table public.communication_preferences enable row level security;alter table public.data_subject_requests enable row level security;alter table public.user_sessions enable row level security;
create policy "users manage preferences" on public.communication_preferences for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "users submit rights requests" on public.data_subject_requests for insert with check(user_id=auth.uid());create policy "users read rights requests" on public.data_subject_requests for select using(user_id=auth.uid());
create policy "users read sessions" on public.user_sessions for select using(user_id=auth.uid());create policy "users revoke sessions" on public.user_sessions for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create index data_subject_queue_idx on public.data_subject_requests(status,due_at);create trigger communication_preferences_updated before update on public.communication_preferences for each row execute function public.set_updated_at();
